usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Evals.Runs.List(
		context.TODO(),
		"eval_id",
		openai.EvalRunListParams{
			After: param.NewOpt[string]("after"),
			Limit: param.NewOpt[int64](20),
			Order: param.NewOpt[openai.EvalsRunsListOrder](openai.EvalsRunsListOrderAsc),
			Status: param.NewOpt[openai.EvalsRunsListStatus](openai.EvalsRunsListStatusQueued),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
